{
  "verdict": "CHANGES",
  "findings": [
    {
      "scope": "SPEC",
      "severity": "high",
      "reference": "Task Card lines 2–4",
      "problem": "The card does not identify which broker-day risk state must be restored, its authoritative source, or how to handle an entry when reconstruction is incomplete.",
      "example": "Specify the drawdown baseline and source data. Restart after a same-day loss breaches the limit and verify that the next entry is blocked. Repeat with required recovery data unavailable and assert the specified failure behavior."
    },
    {
      "scope": "SPEC",
      "severity": "high",
      "reference": "Task Card lines 2 and 5",
      "problem": "The rewind case does not define which broker date governs the decision after the clock moves backward across midnight or how to recover that date's risk state.",
      "example": "Breach the limit on broker day D, advance to D+1 with drawdown below the limit, then rewind to D at 23:59. Specify the expected decision at each transition and again when the clock returns to D+1 at 00:00."
    },
    {
      "scope": "SPEC",
      "severity": "medium",
      "reference": "Task Card lines 2–3 and 5",
      "problem": "The acceptance matrix does not exercise exact equality, so a helper that allows entries at the limit could pass. Lines 2–3 also leave the shared input scale implicit, making the fixture's numeric expectations ambiguous.",
      "example": "State the common normalized scale for drawdown and limit. In that scale, test drawdown just below, exactly at, and just above the limit. Expect allow, block, and block, respectively."
    },
    {
      "scope": "SPEC",
      "severity": "high",
      "reference": "Task Card lines 3 and 5",
      "problem": "The matrix checks entry decisions but does not verify that an entry block leaves exit evaluation independent.",
      "example": "With drawdown above the limit, present a new-entry signal and a valid exit signal for an open position. Verify that the entry is blocked and the exit follows its usual path."
    }
  ]
}
